using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;
internal sealed partial class ControlWindow {
 FileSystemWatcher nameWatch;ImportOperation nameOperation;bool nameBusy;Task nameTask;long nameGeneration,nameChangedTicks;string nameStamp;int unchangedNameAttempts;DateTimeOffset nameNext=DateTimeOffset.MinValue;readonly List<ImportCandidate> nameCandidates=new List<ImportCandidate>();
 void StartNameFlow(){Write("official-name-flow-ready",new{offline=true,scope="registered placeholder names; candidate names are checked only in the explicit import flow",cacheInspectionDeferredUntilRegisteredPlaceholder=true,minimumIntervalSeconds=30,unchangedCacheAttempts=3,noCwpHashing=true});}
 void EnsureNameWatcher(){if(nameWatch!=null||!Directory.Exists(OfficialNames.CacheRoot))return;try{LocalImport.NoLinks(OfficialNames.CacheRoot);nameWatch=new FileSystemWatcher(OfficialNames.CacheRoot){IncludeSubdirectories=false,NotifyFilter=NotifyFilters.FileName|NotifyFilters.LastWrite|NotifyFilters.Size};
  FileSystemEventHandler changed=(s,e)=>{if(NameCacheFile(e.Name))MarkNameCacheChanged();};nameWatch.Changed+=changed;nameWatch.Created+=changed;nameWatch.Deleted+=changed;nameWatch.Renamed+=(s,e)=>{if(NameCacheFile(e.Name)||NameCacheFile(e.OldName))MarkNameCacheChanged();};nameWatch.Error+=(s,e)=>MarkNameCacheChanged();nameWatch.EnableRaisingEvents=true;
 }catch(Exception ex){Write("official-name-watch-unavailable",new{reason=ex.GetType().Name,periodicKnownIndexMetadata=true});}}
 void MarkNameCacheChanged(){Interlocked.Increment(ref nameGeneration);Interlocked.Exchange(ref nameChangedTicks,DateTime.UtcNow.Ticks);}
 static bool NameCacheFile(string name){return name=="index"||System.Text.RegularExpressions.Regex.IsMatch(name??"","^(data_[0-9]{1,3}|f_[0-9a-fA-F]{6})$");}
 string NameCacheStamp(){string p=Path.Combine(OfficialNames.CacheRoot,"index");return Interlocked.Read(ref nameGeneration)+"|"+(File.Exists(p)?new FileInfo(p).Length+"|"+File.GetLastWriteTimeUtc(p).Ticks:"absent");}
 internal static string[] RegisteredNameQueryIds(IEnumerable<WallpaperItem> items){return items.Where(x=>{string suffix,id=OfficialNameStore.ItemId(x);return x.CustomName==null&&id!=null&&OfficialNameStore.Placeholder(x.Name,id,x.RegisteredSha256,out suffix);}).Select(OfficialNameStore.ItemId).Distinct().Take(128).ToArray();}
 internal static bool ShouldInspectOfficialNameCache(string[] ids){return ids!=null&&ids.Length>0;}
 void ObserveNameCandidates(List<ImportCandidate> candidates){nameCandidates.Clear();nameCandidates.AddRange(candidates);nameNext=DateTimeOffset.MinValue;}
 async Task TickOfficialNames(){if(closing||nameBusy||DateTimeOffset.UtcNow<nameNext)return;var ids=RegisteredNameQueryIds(library.Doc.Items).Concat(importDialog!=null&&!importDialog.IsDisposed?nameCandidates.Select(c=>c.Id):Enumerable.Empty<string>()).Where(OfficialNameStore.Id).Distinct().Take(128).ToArray();if(!ShouldInspectOfficialNameCache(ids)){nameNext=DateTimeOffset.UtcNow.AddSeconds(30);return;}EnsureNameWatcher();if(DateTime.UtcNow.Ticks-Interlocked.Read(ref nameChangedTicks)<TimeSpan.FromSeconds(2).Ticks)return;string stamp;try{stamp=NameCacheStamp();}catch{return;}string combined=stamp+"|"+String.Join(",",ids.OrderBy(x=>x));if(combined!=nameStamp){unchangedNameAttempts=0;nameStamp=combined;}if(unchangedNameAttempts>=3){nameNext=DateTimeOffset.UtcNow.AddSeconds(30);return;}
  nameBusy=true;unchangedNameAttempts++;nameNext=DateTimeOffset.UtcNow.AddSeconds(30);nameTask=RefreshOfficialNames(ids);await nameTask;
 }
 async Task RefreshOfficialNames(string[] ids){var op=nameOperation=new ImportOperation(Write);try{var data=await op.Run("names",null,null,0,null,null,ids);if(closing)return;var result=Common.Json.Deserialize<NameRefreshResult>(Common.Json.Serialize(data["names"]));OfficialNameStore.Apply(nameCandidates,result.Names);int changed=OfficialNameStore.ApplyCards(library,result.Names,nameCandidates,Write);if(changed>0)RefreshNameLabels();if(importDialog!=null&&!importDialog.IsDisposed)importDialog.RefreshOfficialNames(result.Names);
   var d=result.Diagnostics;Write("official-name-refresh",new{requestedCount=ids.Length,matchedCount=result.Names.Count,missingCount=result.Missing.Length,reason=result.Reason,changedCards=changed,bodiesRead=result.BodiesRead,playbackRestarted=false,readScope="known official-name cache only",entriesRead=d==null?0:d.EntriesRead,entriesVisited=d==null?0:d.EntriesVisited,moreWork=d!=null&&d.MoreWork,scanCacheHit=d!=null&&d.ScanCacheHit,outcome=d==null?null:d.Outcome,stage=d==null?null:d.Stage,failureKind=d==null?null:d.FailureKind,exceptionType=d==null?null:d.ExceptionType,exceptionMessage=d==null?null:d.ExceptionMessage,indexBytesRead=d==null?0:d.IndexBytesRead,entryBytesRead=d==null?0:d.EntryBytesRead,responseBytesRead=d==null?0:d.ResponseBytesRead,indexMagic=d==null?null:d.IndexMagic,indexVersion=d==null?null:d.IndexVersion,bucketCount=d==null?null:d.BucketCount,recordCount=d==null?null:d.RecordCount,indexLength=d==null?null:d.ActualIndexLength,validationField=d==null?null:d.ValidationField,changedDuringRead=d!=null&&d.ChangedDuringRead});if(d!=null&&d.MoreWork){unchangedNameAttempts=0;nameNext=DateTimeOffset.UtcNow.AddSeconds(2);}
   if(result.Reason!=null&&!(d!=null&&d.MoreWork)){nameNext=DateTimeOffset.UtcNow.AddSeconds(60);if(d!=null&&new[]{"budget","access-denied","unsupported-format","corrupt-cache","read-failure","changed-during-read","io","unexpected"}.Contains(d.FailureKind))RecordFault("name-cover","补充可选壁纸名称","official-name-cache-check",result.Reason,null,null,true);}
  }catch(OperationCanceledException){var d=OfficialNames.LastDiagnostics;Write("official-name-refresh-cancelled",new{namesPreserved=true,outcome=d==null?"cancelled":d.Outcome,stage=d==null?null:d.Stage,failureKind=d==null?"cancelled":d.FailureKind,indexBytesRead=d==null?0:d.IndexBytesRead,entryBytesRead=d==null?0:d.EntryBytesRead,responseBytesRead=d==null?0:d.ResponseBytesRead});}catch(Exception ex){Write("official-name-refresh-failed",new{reason=ex.Message,namesPreserved=true});nameNext=DateTimeOffset.UtcNow.AddSeconds(90);}finally{nameBusy=false;}}
 void RefreshNameLabels(){foreach(WallpaperCard card in cards.Controls){card.AccessibleName=card.Item.Name;card.Invalidate();}selectedName.Text=selected==null?"尚未选择":selected.Name;selectedName.AccessibleDescription=selected==null?"":ResourcePresentation.Id(selected);
  if(importDialog!=null&&!importDialog.IsDisposed)importDialog.RefreshAliases();
  if(activeRunRequest!=null){var active=library.Doc.Items.FirstOrDefault(x=>x.Id==Common.S(activeRunRequest,"selectedCatalogId"));if(active!=null)activeRunName=active.Name;}UpdateFriendlyPlayback();}
 async Task StopNameFlow(){if(nameWatch!=null){nameWatch.Dispose();nameWatch=null;}if(nameOperation!=null&&nameOperation.Busy)nameOperation.Cancel();if(nameTask!=null)await nameTask;Write("official-name-close-clean",new{busy=nameBusy,onlyOwnedNameTask=true});}
}
